-- Rich onboarding sample extras for the mystery workspace.
PRAGMA foreign_keys = ON;
UPDATE projects SET pov='third-person limited (Ritsu Otonashi)', tense='past tense', style_guide='Write observation and deduction concisely. Do not blur fact, testimony, and inference within a paragraph. Plant every decisive clue before the solution. Keep imagery around sound, clocks, and sea fog.', outline='A three-part classic mystery. Part One establishes the storm-bound manor, changed will, impossible bell, and locked-room death. Part Two separates flashback, testimony, and physical evidence to expose a fifteen-minute false time. Part Three reconstructs poisoning before entry and a counterfeit midnight using the wax cylinder and celadon cup.', target_readers='Readers who enjoy fair-play mysteries, isolated manor settings, and testimony dramas in which several different lies overlap.', phase_resolution_mode='reading' WHERE id='default-project';
UPDATE tree_nodes SET intent='Establish the storm-bound manor and the impossible condition that the bell cannot ring.', pov_character_id='sample-codex-ritsu', location_id='sample-codex-manor', chronicle_start_time=305, chronicle_start_minute=1085, chronicle_start_granularity='time', chronicle_precision='exact' WHERE id='sample-scene-1';
UPDATE tree_nodes SET intent='Plant the private celadon cup, changed will, and each suspect''s interest inside an ordinary dinner scene.', pov_character_id='sample-codex-ritsu', location_id='sample-codex-manor', chronicle_start_time=305, chronicle_start_minute=1200, chronicle_start_granularity='time', chronicle_precision='exact' WHERE id='sample-scene-2';
UPDATE tree_nodes SET intent='Present the locked-room death and 11:50 bell so the reader assumes a post-midnight murder.', pov_character_id='sample-codex-ritsu', location_id='sample-codex-tower', chronicle_start_time=306, chronicle_start_minute=10, chronicle_start_granularity='time', chronicle_precision='exact' WHERE id='sample-scene-3';
UPDATE tree_nodes SET intent='Show the pre-discovery positions and give Mio and Toma different reasons to lie.', pov_character_id='sample-codex-ritsu', location_id='sample-codex-manor', chronicle_start_time=305, chronicle_start_minute=1420, chronicle_start_granularity='time', chronicle_precision='exact' WHERE id='sample-scene-4';
UPDATE tree_nodes SET intent='Reverse the locked room from an exit problem into a question about what the victim consumed before entry.', pov_character_id='sample-codex-ritsu', location_id='sample-codex-tower', chronicle_start_time=306, chronicle_start_minute=540, chronicle_start_granularity='time', chronicle_precision='exact' WHERE id='sample-scene-5';
UPDATE tree_nodes SET intent='Use Beats to separate four statements and show that the lies concern place, responsibility, history, and time.', pov_character_id='sample-codex-ritsu', location_id='sample-codex-manor', chronicle_start_time=306, chronicle_start_minute=660, chronicle_start_granularity='time', chronicle_precision='exact' WHERE id='sample-scene-6';
UPDATE tree_nodes SET intent='Reconstruct the false bell and actual death time by ordering the movement of objects.', pov_character_id='sample-codex-ritsu', location_id='sample-codex-manor', chronicle_start_time=306, chronicle_start_minute=900, chronicle_start_granularity='time', chronicle_precision='exact' WHERE id='sample-scene-7';
UPDATE tree_nodes SET intent='Pay off every major clue and unite poisoning, locked room, and false time in one solution.', pov_character_id='sample-codex-ritsu', location_id='sample-codex-manor', chronicle_start_time=306, chronicle_start_minute=1200, chronicle_start_granularity='time', chronicle_precision='exact' WHERE id='sample-scene-8';
UPDATE tree_nodes SET context_mode='suppress', aliases='["feature guide","sample guide"]', excluded_aliases='[]' WHERE id='sample-note-guide';
UPDATE tree_nodes SET context_mode='mentioned', aliases='["time-of-death note","investigation note"]', excluded_aliases='[]' WHERE id='sample-note-case';
UPDATE tree_nodes SET placed_beat_preview='["Ritsu arrives. Establish that the bell cannot ring and isolate the manor in the storm."]' WHERE id='sample-scene-1';
UPDATE tree_nodes SET placed_beat_preview='["Mio: a lie about place","Chikage: a lie about medicine control","Maho: tableware and bell procedure","Toma: a lie about time"]' WHERE id='sample-scene-6';
UPDATE tree_nodes SET unplaced_beats_doc='[{"id":"sample-unplaced-1","beatType":"summary","pov":"sample-codex-ritsu","collapsed":false,"content":[{"type":"text","text":"Arrange the movement of tableware, cylinder, and people on one timeline."}]},{"id":"sample-unplaced-2","beatType":"guided","pov":"sample-codex-ritsu","collapsed":false,"content":[{"type":"text","text":"State the contradiction between the 11:47 watch and the 11:50 bell."}]},{"id":"sample-unplaced-3","beatType":"dialogue","pov":"sample-codex-toma","collapsed":false,"content":[{"type":"text","text":"Make Toma describe the direction of the bell again and contrast it with the others."}]},{"id":"sample-unplaced-4","beatType":"setting","pov":null,"collapsed":false,"content":[{"type":"text","text":"Inspect the conservatory irrigation timer and phonograph; rain masks small mechanical sounds."}]},{"id":"sample-unplaced-5","beatType":"micro","pov":null,"collapsed":false,"content":[{"type":"text","text":"Return to Ritsu''s Chapter One note: the bell will not ring tonight."}]}]', unplaced_beat_preview='["Arrange the movement of tableware, cylinder, and people on o","State the contradiction between the 11:47 watch and the 11:5","Make Toma describe the direction of the bell again and contr","Inspect the conservatory irrigation timer and phonograph; ra","Return to Ritsu''s Chapter One note: the bell will not ring t"]' WHERE id='sample-scene-7';
